(function(){
'use strict';
const T=window.NavigatorTimeline;let state=T.create(),timer,recordDraft=()=>false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={receipt:'Complaint received by Committee',commenced:'Verified inquiry commencement',firstMeeting:'First Committee meeting',completed:'Inquiry completed',reportSubmitted:'Report provided to employer / District Officer',partiesSupplied:'Report made available to concerned parties',recommendationsReceived:'Recommendations actually received by employer / District Officer',implemented:'Implementation / action completed (settlement or recommendations)',conciliationRequested:'Aggrieved woman requested conciliation',settled:'Settlement recorded',settlementForwarded:'Settlement forwarded to employer / District Officer',settlementCopies:'Settlement copies provided to parties',breachReported:'Settlement breach reported by aggrieved woman'};
function render(app){
 clearInterval(timer);app.innerHTML=`<section class="app-heading"><div class="wrap"><a href="#demo">← Inquiry stages</a><h1>Guided IC / LC Inquiry</h1><p>Timeline and follow-up review · staged within POSH Inquiry Navigator</p></div></section><div class="wrap timeline-workspace"><p class="notice warning">Staging review: use fictional procedural references only. Records stay in this tab until exported; reloading loses them. No background, email or external escalation is sent. Exported history is a review record, not a tamper-proof institutional audit log.</p><details><summary>Verified statutory triggers and safeguards</summary><p>Section 11(4) requires inquiry completion within 90 days. It does not expressly define a commencement event. Record the competent reviewer’s verified initiation date and basis, separately from the first meeting. Receipt-based monitoring remains visible to flag delay. Calendar-day calculations exclude the trigger date and do not automatically extend for holidays.</p><p>Section 13(1): report within 10 calendar days of inquiry completion; make it available to concerned parties. Section 13(4): action within 60 calendar days of the recipient’s receipt of recommendations. Section 12 interim relief carries no statutory pause or extension of these periods.</p><p>Applicable Central Rule 7: complaint copy within 7 working days of complaint receipt; reply within 10 working days of actual receipt of prescribed documents. Verify service / sector rules and the working calendar. Rule 7(5) requires three consecutive absences without sufficient cause and written notice 15 days in advance before termination / ex parte decision; Rule 7(7) requires three members including the Presiding Officer / Chairperson. No automatic adverse order is generated.</p><p>Section 10: only on the woman’s request before inquiry; no monetary settlement as its basis. Record settlement, forwarding and party copies. Breach reported by the woman returns for action under Section 11(1). Domestic-worker prima facie referral, jurisdiction, bias, absence, withdrawal, court directions and disputed dates require competent review, not automatic closure.</p><a href="https://www.indiacode.nic.in/bitstream/123456789/2104/1/A2013-14.pdf" target="_blank" rel="noopener">Act</a> · <a href="https://nhrc.nic.in/assets/uploads/training_projects/NHRC_Study_rpt_sexual_harrasemnt_workplaceDec2023.pdf" target="_blank" rel="noopener">Reproduced Act and Central Rules: annexures A–B</a></details><form id="timeline-review"><h2>Responsible review</h2><div class="timeline-grid"><label>Reviewer reference<input name="actor" required maxlength="100" placeholder="Committee reviewer code"></label><label>Reason / record reference<input name="reason" required maxlength="250"></label></div><h2>Route and applicable procedure</h2><label>Principal route<select name="route"><option value="inquiry">Sections 11–13 inquiry and report</option><option value="conciliation">Section 10 conciliation</option></select></label><label>Applicable service / sector rules and verification record<input name="procedure" maxlength="250"></label><label><input type="checkbox" name="centralRules"> Central Rule 7 verified as applicable</label><label><input type="checkbox" name="commencementVerified"> Competent reviewer verified inquiry commencement</label><label>Commencement basis / Committee initiation record<input name="commencementBasis" maxlength="250"></label><h3>Working calendar for Rule 7</h3><label><input type="checkbox" name="calendarVerified"> Applicable calendar verified</label><label>Non-working weekdays (0 Sunday to 6 Saturday; comma separated)<input name="weekends" value="0,6"></label><label>Non-working holidays (YYYY-MM-DD, comma separated)<input name="holidays"></label><h3>Section 10 verification</h3>${[['requestByWoman','Request is by the aggrieved woman'],['voluntary','Request is voluntary'],['noMonetaryBasis','Monetary settlement is not the basis']].map(([name,label])=>`<label><input type="checkbox" name="${name}"> ${label}</label>`).join('')}<label>Procedural exception requiring review<select name="exception"><option value="">None recorded</option>${['Unverified / disputed dates','Settlement breach / resumption','Absence / ex parte / termination review','Jurisdiction / Committee conflict / quorum','Domestic-worker prima facie police referral','Interim relief / safety','Adjournment / stay / court direction','Withdrawal / other procedural issue'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="btn btn-dark">Record review settings</button></form><form id="timeline-date"><h2>Actual milestone</h2><label>Milestone<select name="key">${T.fields.map(k=>`<option value="${k}">${labels[k]}</option>`).join('')}</select></label><label>Verified actual date<input type="date" name="value"></label><p>Leave date blank only to correct an erroneous entry. The old value remains in history. Use the review identity and reason above for each change.</p><button class="btn btn-dark">Record milestone</button></form><form id="timeline-event"><h2>Every hearing, meeting and procedural event</h2><label>Existing event to update<select name="id" id="event-id"><option value="">New event</option></select></label><div class="timeline-grid"><label>Kind<select name="kind">${['meeting','hearing','notice','response','evidence','witness','complaintSent','documentsReceived','reply','interimRelief','followup','exception'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Event date<input type="date" name="date" required></label><label>Status<select name="status"><option value="planned">Planned</option><option value="done">Done</option><option value="cancelled">Cancelled with review</option></select></label><label>Record reference (no testimony or names)<input name="reference" required maxlength="150"></label><label>Responsible owner code<input name="owner" maxlength="100"></label><label>Next follow-up / review date<input type="date" name="followupDue"></label></div><p>Each subsequent hearing has its own record. Use notice / response / evidence / witness events for their dates. A planned event requires an owner and review date. Record attendance, service proof and procedural decisions in your controlled institutional record, referenced here.</p><button class="btn btn-dark">Record event / correction</button></form><p id="timeline-error" role="alert"></p><section id="timeline-status" aria-live="polite"></section><h2>Event record</h2><div id="timeline-events"></div><h2>Audit trail</h2><button type="button" class="btn btn-light" id="timeline-export">Export timeline and full audit JSON</button><label>Restore an exported staging record<input type="file" id="timeline-import" accept="application/json,.json"></label><p>Imported history is untrusted and is labelled as restored. It does not verify identity or authenticate institutional records.</p><div id="timeline-audit"></div></div>`;
 const review=app.querySelector('#timeline-review'),dates=app.querySelector('#timeline-date'),events=app.querySelector('#timeline-event'),error=app.querySelector('#timeline-error');
 function commit(command,identity){try{state=T.change(state,command,identity?.actor||review.elements.actor.value,identity?.reason||review.elements.reason.value);error.textContent='';refresh();return true;}catch(e){error.textContent=e.message;return false;}}
 review.onsubmit=e=>{e.preventDefault();const f=review.elements;const weekends=f.weekends.value.split(',').filter(x=>x.trim()).map(Number);if(weekends.some(x=>!Number.isInteger(x)||x<0||x>6)||new Set(weekends).size===7){error.textContent='Enter a valid working week with at least one working day.';return;}commit({type:'settings',value:{route:f.route.value,procedure:f.procedure.value,centralRules:f.centralRules.checked,commencementVerified:f.commencementVerified.checked,commencementBasis:f.commencementBasis.value,calendar:{verified:f.calendarVerified.checked,weekends,holidays:f.holidays.value.split(',').map(x=>x.trim()).filter(Boolean)},conciliation:{requestByWoman:f.requestByWoman.checked,voluntary:f.voluntary.checked,noMonetaryBasis:f.noMonetaryBasis.checked},exception:f.exception.value||null}});};
 dates.onsubmit=e=>{e.preventDefault();commit({type:'date',key:dates.elements.key.value,value:dates.elements.value.value});};dates.elements.key.onchange=()=>dates.elements.value.value=state.dates[dates.elements.key.value]||'';
 events.onsubmit=e=>{e.preventDefault();const value=Object.fromEntries(new FormData(events));commit({type:'event',value});};events.elements.id.onchange=()=>{const item=state.events.find(x=>x.id===events.elements.id.value);if(item)for(const [k,v] of Object.entries(item))if(events.elements[k])events.elements[k].value=v;};
 function sync(){const f=review.elements;for(const k of ['route','procedure','commencementBasis'])f[k].value=state[k];for(const k of ['centralRules','commencementVerified'])f[k].checked=state[k];f.exception.value=state.exception||'';f.calendarVerified.checked=state.calendar.verified;f.weekends.value=state.calendar.weekends.join(',');f.holidays.value=state.calendar.holidays.join(',');for(const k of ['requestByWoman','voluntary','noMonetaryBasis'])f[k].checked=!!state.conciliation[k];}
 function refresh(){const result=T.evaluate(state),status=app.querySelector('#timeline-status');status.innerHTML=`<h2>${result.canClose?'Principal flow recorded as complete':'Outstanding actions'}</h2><p>${esc(result.flow)} · Revision ${state.revision}. Closure is a record check; the competent Committee makes legal decisions.</p>${result.items.map(x=>`<article class="timeline-alert"><strong>${esc(x.status.toUpperCase())} · ${esc(x.label||x.message)}</strong>${x.due?`<p>Due ${esc(x.due)}${x.done?' · Recorded '+esc(x.done):''} · Owner: ${esc(x.owner)}</p>`:''}<p>${esc(x.action)}</p></article>`).join('')}`;app.querySelector('#timeline-events').innerHTML=state.events.map(x=>`<p>${esc(x.date)} · ${esc(x.kind)} · ${esc(x.reference)} · ${esc(x.status)} · ${esc(x.owner)}</p>`).join('')||'<p>No events recorded. Add the next owned follow-up.</p>';app.querySelector('#timeline-audit').innerHTML=state.audit.slice().reverse().map(x=>`<details><summary>Revision ${x.revision} · ${esc(x.at)} · ${esc(x.actor)}</summary><p>${esc(x.reason)}</p><pre>${esc(JSON.stringify(x,null,2))}</pre></details>`).join('');const selection=events.elements.id.value;events.elements.id.innerHTML='<option value="">New event</option>'+state.events.map(x=>`<option value="${esc(x.id)}">${esc(x.date+' '+x.kind+' '+x.reference)}</option>`).join('');events.elements.id.value=selection;window.dispatchEvent(new Event('navigator:timeline-changed'));}
 app.querySelector('#timeline-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='POSH-staging-timeline.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 app.querySelector('#timeline-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Record too large.');const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.audit)||data.audit.length>5000)throw Error('Unsupported timeline record.');let restored=T.create();for(const entry of data.audit){if(entry.command?.type==='restore')continue;restored=T.change(restored,entry.command,entry.actor,entry.reason,entry.at);}if(JSON.stringify({...restored,audit:[]})!==JSON.stringify({...data,audit:[]}))throw Error('History does not reproduce the saved record.');state=restored;error.textContent='Restored untrusted staging history. Verify source records independently.';sync();refresh();}catch(ex){error.textContent='Import failed: '+ex.message;}};
 recordDraft=(id,identity)=>commit({type:'document',id},identity);sync();refresh();timer=setInterval(()=>{if(!document.contains(app.querySelector('#timeline-status'))){clearInterval(timer);return;}refresh();},60000);
}
window.NavigatorTimelineUI={render,getResult:()=>T.evaluate(state),getDates:()=>({...state.dates}),recordDocument:(id,identity)=>recordDraft(id,identity)};
})();
